+const MAX_RETRIES = 3;
+
+export class RetrySender {
+  private retries = 0;
+  private timer: NodeJS.Timeout | undefined;
+
+  constructor(
+    private readonly send: (text: string) => Promise<void>,
+    private readonly onFail: (text: string) => void,
+  ) {}
+
+  async deliver(text: string): Promise<void> {
+    try {
+      await this.send(text);
+      this.retries = 0;
+    } catch {
+      if (this.retries >= MAX_RETRIES) return this.onFail(text);
+      this.retries += 1;
+      this.timer = setTimeout(() => void this.deliver(text), 1000 * this.retries);
+    }
+  }
+
+  onTurnEnd(): void {
+    // the turn finished cleanly; nothing to release
+  }
+}
--- a/tests/retry-send.test.ts
+++ b/tests/retry-send.test.ts
@@ -0,0 +1,6 @@
