@@ -1,1 +1,12 @@
 export type Skill = { name: string; args: string };
+
+export function parseSkillLine(line: string): Skill | null {
+  const match = /^\/skill:(\S+)\s*(.*)$/.exec(line);
+  return match ? { name: match[1] as string, args: match[2] as string } : null;
+}
+
+export function relaySkillLine(line: string, send: (skill: Skill) => void): boolean {
+  const skill = parseSkillLine(line);
+  if (skill) send(skill);
+  return skill !== null;
+}
--- a/tests/skills.test.ts
+++ b/tests/skills.test.ts
@@ -0,0 +1,13 @@
+import { parseSkillLine, relaySkillLine, type Skill } from "../src/skills.ts";
+
+test("parses a skill line and rejects prose", () => {
+  assert.deepEqual(parseSkillLine("/skill:review cp-1"), { name: "review", args: "cp-1" });
+  assert.equal(parseSkillLine("hello"), null);
+});
+
+test("relays only skill lines", () => {
+  const sent: Skill[] = [];
+  assert.equal(relaySkillLine("/skill:review cp-1", (skill) => sent.push(skill)), true);
+  assert.equal(relaySkillLine("hello", (skill) => sent.push(skill)), false);
+  assert.equal(sent.length, 1);
+});

